[{"name":"Write","arguments":{"content":""""Deterministic logical-time event scheduler. Stdlib only, single-threaded."""

import heapq


class _Event:
    __slots__ = ("time", "priority", "seq", "callback", "args", "cancelled")

    def __init__(self, time, priority, seq, callback, args):
        self.time = time
        self.priority = priority
        self.seq = seq
        self.callback = callback
        self.args = args
        self.cancelled = False

    def __lt__(self, other):
        if self.time != other.time:
            return self.time < other.time
        if self.priority != other.priority:
            return self.priority < other.priority
        return self.seq < other.seq


class _Handle:
    __slots__ = ("event",)

    def __init__(self, event):
        self.event = event


class Scheduler:
    """Boringly deterministic event scheduler over logical time.

    Ordering at equal timestamps: lower priority number first, then the
    order in which events were scheduled. No wall clock, no randomness.
    """

    def __init__(self):
        self._queue = []          # heap of _Event
        self._seq = 0             # global scheduling-order counter
        self._now = 0

    @property
    def now(self):
        return self._now

    @property
    def pending(self):
        return sum(1 for ev in self._queue if not ev.cancelled)

    def schedule(self, delay, callback, *args, priority=0):
        if delay < 0:
            raise ValueError("delay must be non-negative")
        self._seq += 1
        ev = _Event(self._now + delay, priority, self._seq, callback, args)
        heapq.heappush(self._queue, ev)
        return _Handle(ev)

    def cancel(self, handle):
        ev = handle.event
        if ev.cancelled or ev.callback is None:
            return False
        ev.cancelled = True
        ev.callback = None
        return True

    def _pop_due(self, horizon):
        """Pop and return the next armed event with time <= horizon, or None.

        Fired or cancelled events are discarded lazily. Mutations made by
        callbacks are visible because the heap is re-examined each time.
        """
        while self._queue:
            ev = self._queue[0]
            if ev.time > horizon:
                return None
            heapq.heappop(self._queue)
            if not ev.cancelled and ev.callback is not None:
                return ev
        return None

    def _fire(self, ev):
        callback, args = ev.callback, ev.args
        ev.callback = None        # counts as fired from this point on
        self._now = ev.time
        callback(*args)

    def run_until(self, t):
        if t < self._now:
            raise ValueError("cannot run until a time before now")
        while True:
            ev = self._pop_due(t)
            if ev is None:
                break
            self._fire(ev)
        self._now = t

    def run_next(self):
        ev = self._pop_due(self._now)
        # Look past cancelled entries without advancing time for them.
        while ev is None and self._queue and self._queue[0].time > self._now:
            cand = self._queue[0]
            if cand.cancelled or cand.callback is None:
                heapq.heappop(self._queue)
                continue
            ev = cand
            break
        if ev is None:
            return None
        self._fire(ev)
        return ev.time
