class Autocomplete:
    """Accumulates weighted search terms and suggests ranked matches."""

    def __init__(self):
        self._weights = {}

    @staticmethod
    def _normalize(term):
        if not isinstance(term, str):
            raise ValueError("term must be a string")
        trimmed = term.strip()
        if not trimmed:
            raise ValueError("term must not be empty")
        return trimmed.lower()

    def insert(self, term, weight=1):
        key = self._normalize(term)
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise ValueError("weight must be a positive int")
        if weight <= 0:
            raise ValueError("weight must be a positive int")
        self._weights[key] = self._weights.get(key, 0) + weight

    def suggest(self, prefix, limit=5):
        if not isinstance(prefix, str):
            return []
        key = prefix.strip().lower()
        matches = [t for t in self._weights if t.startswith(key)]
        matches.sort(key=lambda t: (-self._weights[t], t))
        return matches[:limit]

    def count(self, term):
        if not isinstance(term, str):
            return 0
        return self._weights.get(term.strip().lower(), 0)

    def __contains__(self, term):
        return self.count(term) > 0

    def __len__(self):
        return len(self._weights)

    def delete(self, term):
        if not isinstance(term, str):
            return False
        return self._weights.pop(term.strip().lower(), None) is not None
