# Dot-source this file; exports Build-ShiftBrief -Path <logfile>.
# Linear build: one pass over the lines appending into a single StringBuilder,
# never string concatenation (the old += prototype was quadratic).

function Build-ShiftBrief {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "briefkit: log not found: $Path"
    }

    $lines = [System.IO.File]::ReadAllLines($Path)

    $sb = [System.Text.StringBuilder]::new()
    $null = $sb.Append("shift brief`n")

    $entries = 0
    $skipped = 0
    # Ordinal, case-sensitive level counts: WARN and warn must stay distinct.
    $levels = [System.Collections.Generic.Dictionary[string, int]]::new([System.StringComparer]::Ordinal)

    $sep = [char[]]@(' ')

    foreach ($line in $lines) {
        if ($line.Length -eq 0) { continue }
        if ([string]::IsNullOrWhiteSpace($line)) { continue }

        $fields = $line.Split($sep)
        if ($fields.Count -ne 5) {
            $skipped++
            continue
        }
        $glitch = $false
        foreach ($f in $fields) {
            if ($f.Length -eq 0) { $glitch = $true; break }
        }
        if ($glitch) {
            $skipped++
            continue
        }

        $entries++
        $level = $fields[2]
        if ($levels.ContainsKey($level)) {
            $levels[$level]++
        } else {
            $levels[$level] = 1
        }

        $null = $sb.Append($entries.ToString('d7'))
        $null = $sb.Append(' ')
        # level padded right to 5
        $null = $sb.Append($level)
        for ($p = $level.Length; $p -lt 5; $p++) { $null = $sb.Append(' ') }
        $null = $sb.Append(" $($fields[0])/$($fields[1]) $($fields[3])ms $($fields[4])`n")
    }

    $null = $sb.Append("entries: $entries`n")
    $null = $sb.Append("skipped: $skipped`n")

    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($k in $levels.Keys) { $names.Add($k) }
    $names.Sort([System.StringComparer]::Ordinal)
    foreach ($name in $names) {
        $null = $sb.Append("level $name: $($levels[$name])`n")
    }

    return $sb.ToString()
}
